                              statusLine: lastAtt?.status_line ?? null,
                              goalId: props.id, relaunchKind: "exec",
                              relaunchRoute, onRelaunched: setRelaunchRoute,
                              // g-190：解绑控件数据（attemptId/bindingToken；成功解绑后刷新详情与看板）
                              attemptId: att.id,
